$(function () {
  let image = &quot;%2fPCUP%2fReligion-PNG%2fLamashtu.png&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;#symbole1&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td id=&quot;symbole1&quot; style=&quot;text-align:center;&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux aux fid&#232;les de la divinit&#233; indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Lamashtu (technique).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/%2fPCUP%2fReligion-PNG%2fLamashtu.png&quot; style=&quot;max-height:70px; max-width:70px&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br/&gt;commune chez&lt;br/&gt;les fid&#232;les&lt;br/&gt;de &lt;a class=&quot;pagelink&quot; href=&quot;Lamashtu-(Technique).html&quot; title=&quot;Lamashtu&quot;&gt;Lamashtu&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Fille de Rouge-D&#233;sir&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Dieux de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Gods/Dieux de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Evocation.html&quot; title=&quot;&#201;vocation&quot;&gt;&#201;vocation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Necromancie.html&quot; title=&quot;N&#233;cromancie&quot;&gt;N&#233;cromancie&lt;/a&gt;, et &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; mod&#233;r&#233;e ; &lt;b&gt;NLS&lt;/b&gt; 10 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques-Sp&#233;cifiques.html&quot; title=&quot;Armes magiques sp&#233;cifiques&quot;&gt;aucun (arme)&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 9 875 po ; &lt;b&gt;Poids&lt;/b&gt; 4 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Ce &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cimeterre-&#192;-Deux-Mains-(Arme).html&quot; title=&quot;Cimeterre &#224; deux mains&quot;&gt;cimeterre &#224; deux mains&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;feu&lt;/a&gt; +1&lt;/i&gt; est grav&#233; de visages d&#233;moniaques &#224; la langue longue et &#224; l&#39;expression lugubre. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le porteur peut transformer l&#39;arme en &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kukri-(Arme).html&quot; title=&quot;Kukri&quot;&gt;kukri&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;feu&lt;/a&gt; +1&lt;/i&gt; ou lui rendre sa forme initiale par la force de sa volont&#233;. L&#39;arme a une affinit&#233; pour le sang humano&#239;de et reste glissante et humide longtemps apr&#232;s qu&#39;elle ait normalement s&#233;ch&#233;. Si le porteur tue un humano&#239;de avec la &lt;i&gt;fille de Rouge-D&#233;sir&lt;/i&gt;, il peut l&#233;cher ce sang par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; pour r&#233;cup&#233;rer 1d4 points de vie. L&#39;&#233;glise de &lt;a class=&quot;pagelink&quot; href=&quot;Lamashtu-(Technique).html&quot; title=&quot;Lamashtu&quot;&gt;Lamashtu&lt;/a&gt; cr&#233;e &#233;galement une arme similaire, la &lt;i&gt;fille de Cœur-froid&lt;/i&gt;, qui est un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cimeterre-&#192;-Deux-Mains-(Arme).html&quot; title=&quot;Cimeterre &#224; deux mains&quot;&gt;cimeterre &#224; deux mains&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Froid.html&quot; title=&quot;froid (propri&#233;t&#233;)&quot;&gt;froid&lt;/a&gt; +1&lt;/i&gt; ayant les m&#234;mes propri&#233;t&#233;s que cette arme.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d&#39;armes et armures magiques&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Colonne-De-Feu.html&quot; title=&quot;Colonne de feu&quot;&gt;colonne de feu&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mise-&#192;-Mort.html&quot; title=&quot;Mise &#224; mort&quot;&gt;mise &#224; mort&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-Dobjet.html&quot; title=&quot;R&#233;duction d&amp;#39;objet&quot;&gt;r&#233;duction d&#39;objet&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 5 125 po
&lt;/div&gt;
